namespace resources {

enum ResourceMode { ResourceModeDir, ResourceModeBundle, ResourceModeEmbedded };

fs::FileReaderResult getFile(const string &filename);
bool extractFile(const string &filename, const string &outputFilename);
void init();
void setMode(const resources::ResourceMode mode);
resources::ResourceMode getMode();
bool isDirMode();
bool isBundleMode();
bool isEmbeddedMode();
string getModeString();
json getFileTree();

} // namespace resources

struct CliArg {
    string key;
    string value;
};

struct ConfigOverride {
    string key;
    string value;
    string convertTo;
};

struct FileReaderResult {
    errors::StatusCode status = errors::NE_ST_OK;
    string data;
};

struct FileReaderOptions {
    long long pos = -1;
    long long size = -1;
};

struct FileWriterOptions {
    string filename;
    string data;
    bool append = false;
};

struct OpenedFileEvent {
    int id = -1;
    string type = "";
    long long pos = -1;
    long long size = -1;
};

struct FileStats {
    errors::StatusCode status = errors::NE_ST_OK;
    long long size;
    fs::EntryType entryType = fs::EntryTypeOther;
    long long createdAt;
    long long modifiedAt;
};

struct DirReaderEntry {
    string name;
    string path;
    fs::EntryType type = fs::EntryTypeOther;
};

struct DirReaderResult {
    errors::StatusCode status = errors::NE_ST_OK;
    vector<DirReaderEntry> entries;
};

struct CommandResult {
    int pid = -1;
    int exitCode = -1;
    string stdErr = "";
    string stdOut = "";
};

struct SpawnedProcessEvent {
    int id = -1;
    string type = "";
    string stdIn = "";
};

struct ChildProcessOptions {
    bool background = false;
    bool events = true;
    string cwd = "";
    string stdIn = "";
    map<string, string> envs;
    function<void(const char *bytes, size_t n)> stdOutHandler;
    function<void(const char *bytes, size_t n)> stdErrHandler;
};

